import pathlib,time
SETTINGS=['tidb_executor_concurrency','tidb_distsql_scan_concurrency','tidb_max_chunk_size','tidb_enable_paging','tidb_max_paging_size','tidb_min_paging_size','tidb_mem_quota_query']
def profile(conn, sql, quota):
    with conn.cursor() as cur:
        cur.execute('SELECT '+','.join('@@'+name for name in SETTINGS));previous=cur.fetchone()
    try:
        with conn.cursor() as cur:
            for name,value in zip(SETTINGS,[1,1,128,1,128,128,quota]):cur.execute('SET SESSION '+name+'=%s',(value,))
            try:
                cur.execute('EXPLAIN ANALYZE '+sql);return {'plan':cur.fetchall(),'error':None}
            except Exception as error:
                if not getattr(error,'args',()) or not isinstance(error.args[0],int):raise
                return {'plan':None,'error':list(error.args)}
    finally:
        with conn.cursor() as cur:
            for name,value in zip(SETTINGS,previous):cur.execute('SET SESSION '+name+'=%s',(value,))
def cancel_and_reclaim(control, connection_id, spill_dir, seconds):
    start=time.monotonic()
    with control.cursor() as cur:cur.execute('KILL TIDB QUERY '+str(int(connection_id)))
    while time.monotonic()-start<seconds:
        with control.cursor() as cur:
            cur.execute('SELECT ID,INFO FROM information_schema.processlist WHERE ID=%s',(connection_id,));rows=cur.fetchall()
        files=[p for p in pathlib.Path(spill_dir).rglob('*') if p.is_file() and p.stat().st_size>0]
        if (not rows or rows[0][1] is None) and not files:return {'state':'cancelled','remaining_bytes':0}
        time.sleep(.03)
    raise TimeoutError('Server query or owned spill files remain after cancellation budget')
