def transfer(conn, operation_id, source_id, target_id, amount, before_commit=None):
    if amount<=0 or source_id==target_id:raise ValueError('invalid transfer')
    with conn.cursor() as cur:
        cur.execute('SELECT @@tidb_txn_mode');previous=cur.fetchone()[0]
        cur.execute("SET SESSION tidb_txn_mode='pessimistic'")
    retried=False
    try:
        for attempt in range(2):
            conn.begin()
            try:
                with conn.cursor() as cur:
                    cur.execute('SELECT source_id,target_id,amount FROM transfers WHERE operation_id=%s FOR UPDATE',(operation_id,));existing=cur.fetchone()
                    if existing:
                        if tuple(existing)!=(source_id,target_id,amount):raise ValueError('idempotency key payload conflict')
                        conn.rollback();return {'status':'already_applied','retried':retried}
                    cur.execute('INSERT INTO transfers VALUES(%s,%s,%s,%s)',(operation_id,source_id,target_id,amount))
                    cur.execute('UPDATE accounts SET balance=balance-%s WHERE id=%s AND balance>=%s',(amount,source_id,amount))
                    if cur.rowcount!=1:
                        conn.rollback();return {'status':'insufficient','retried':retried}
                    cur.execute('UPDATE accounts SET balance=balance+%s WHERE id=%s',(amount,target_id))
                    if cur.rowcount!=1:raise ValueError('target account missing')
                if attempt==0 and before_commit is not None:before_commit(conn)
                conn.commit();return {'status':'applied','retried':retried}
            except Exception as error:
                conn.rollback()
                lost=bool(getattr(error,'args',())) and error.args[0]==1105 and 'PessimisticLockNotFound' in str(error)
                if attempt==0 and lost:retried=True;continue
                raise
        raise RuntimeError('retry exhausted')
    finally:
        with conn.cursor() as cur:cur.execute('SET SESSION tidb_txn_mode=%s',(previous,))
