def baseline(conn):
 available={r[0] for r in query(conn,'SHOW TABLES FROM mysql')}
 privileges=[]
 for table in ['user','db','tables_priv','columns_priv','default_roles','role_edges','global_grants','global_priv']:
  if table in available:
   rows=query(conn,'SELECT * FROM mysql.`'+table+'`')
   privileges.append((table,hashlib.sha256(repr(sorted(rows,key=repr)).encode()).hexdigest()))
 return (query(conn,'SELECT CURRENT_USER(),@@global.tidb_txn_mode,@@global.tidb_enable_metadata_lock,@@global.allow_auto_random_explicit_insert'),query(conn,'SHOW GRANTS'),privileges)
def session(conn):
 return query(conn,'SELECT @@tidb_txn_mode,@@transaction_isolation,@@tidb_snapshot,@@autocommit')
def compact_sql(sql):return re.sub(r'\s+','',sql).replace('`','').lower().rstrip(';')
class TraceCursor:
 def __init__(self,cursor,owner):self.cursor=cursor;self.owner=owner;self.statement='';self.params=None
 def __enter__(self):self.cursor.__enter__();return self
 def __exit__(self,*args):return self.cursor.__exit__(*args)
 def __getattr__(self,name):return getattr(self.cursor,name)
 def execute(self,statement,params=None):
  self.statement=statement;self.params=params
  return self.cursor.execute(statement,params)
 def fetchall(self):
  rows=self.cursor.fetchall();self.owner.observed.append((self.statement,self.params,rows));return rows
 def fetchone(self):
  row=self.cursor.fetchone();self.owner.observed.append((self.statement,self.params,(row,)));return row
class Trace:
 def __init__(self,conn):self.conn=conn;self.observed=[]
 def cursor(self,*args,**kwargs):return TraceCursor(self.conn.cursor(*args,**kwargs),self)
 def __getattr__(self,name):return getattr(self.conn,name)

class WritesCursor(TraceCursor):
 def execute(self,sql,params=None):self.owner.executed.append((sql,params));return super().execute(sql,params)
class WritesTrace(Trace):
 def __init__(self,conn):super().__init__(conn);self.executed=[]
 def cursor(self,*args,**kwargs):return WritesCursor(self.conn.cursor(*args,**kwargs),self)
